'use strict';
// Replace only with approved Alami media and the owner's international digits-only number.
const VILLA_CONFIG={whatsapp:'',heroVideo:'assets/alami-escape.mp4'};
const $=(s,root=document)=>root.querySelector(s),$$=(s,root=document)=>[...root.querySelectorAll(s)];
const reduceMotion=matchMedia('(prefers-reduced-motion: reduce)').matches;
if(!reduceMotion&&'IntersectionObserver' in window){document.documentElement.classList.add('motion-ready');const revealObserver=new IntersectionObserver(entries=>entries.forEach(entry=>entry.target.classList.toggle('visible',entry.isIntersecting)),{threshold:0,rootMargin:'0px 0px -30px 0px'});$$('.reveal').forEach(el=>revealObserver.observe(el));}
const panel=$('#mobilePanel'),menu=$('#menuButton');let previousFocus;
function setMenu(on){if(on)previousFocus=document.activeElement;panel.classList.toggle('open',on);document.body.classList.toggle('menu-open',on);menu.setAttribute('aria-expanded',String(on));if(on)$('#closeMenu').focus();else if(previousFocus)previousFocus.focus();}
menu.addEventListener('click',()=>setMenu(true));$('#closeMenu').addEventListener('click',()=>setMenu(false));$$('a',panel).forEach(a=>a.addEventListener('click',()=>setMenu(false)));
function trapFocus(e,container){if(e.key!=='Tab')return;const items=$$('a[href],button,input,select,textarea,[tabindex="0"]',container).filter(el=>!el.hidden&&el.offsetParent!==null),first=items[0],last=items.at(-1);if(!first)return;if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}
panel.addEventListener('keydown',e=>trapFocus(e,panel));
const film=$('#villaFilm'),filmControl=$('#filmControl');
if(film){film.muted=true;film.defaultMuted=true;film.playsInline=true;film.src=VILLA_CONFIG.heroVideo;function labelFilm(){filmControl.innerHTML=film.paused?'▶ <span>Play film</span>':'Ⅱ <span>Pause film</span>';filmControl.setAttribute('aria-label',film.paused?'Play background film':'Pause background film')}film.addEventListener('play',labelFilm);film.addEventListener('pause',labelFilm);film.addEventListener('error',()=>{film.style.display='none';filmControl.hidden=true});filmControl.addEventListener('click',()=>{if(film.paused)film.play().catch(labelFilm);else film.pause()});if(reduceMotion){film.autoplay=false;film.pause();labelFilm()}else film.play().catch(labelFilm);}
let queued=false;function updateScroll(){const y=scrollY,h=innerHeight,doc=document.documentElement;const mobile=matchMedia('(max-width:760px)').matches;$('.scroll-progress').style.width=(y/Math.max(1,doc.scrollHeight-h)*100)+'%';$('.site-header').classList.toggle('scrolled',y>90);if(!reduceMotion){const hc=$('.hero-content');if(hc){hc.style.opacity=String(1-Math.min(1,y/(Math.max(h,$('.hero')?.offsetHeight||h)*.8)));hc.style.translate='0 '+Math.round(y*(mobile?.08:.17))+'px'}$$('[data-parallax]').forEach(p=>{const r=p.parentElement.getBoundingClientRect();if(r.bottom>0&&r.top<h)p.style.transform='translateY('+((h/2-r.top-r.height/2)*(mobile?.045:.12))+'px)'})}queued=false}addEventListener('scroll',()=>{if(!queued){requestAnimationFrame(updateScroll);queued=true}},{passive:true});updateScroll();
const spaces=[['Bedroom One','A place to retreat, rest, and begin another unhurried morning. One of the villa’s two private bedrooms.','assets/bedroom-one.jpg'],['Bedroom Two','A second private bedroom, made for time away together while keeping a little space of your own.','assets/bedroom-two.jpg'],['Your Private Pool','The centre of slow afternoons. A large private pool, reserved for your villa escape.','assets/pool.jpg']];
$$('[data-space]').forEach(button=>button.addEventListener('click',()=>{const info=spaces[Number(button.dataset.space)];$$('[data-space]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));$('#spaceTitle').textContent=info[0];$('#spaceCopy').textContent=info[1];$('#spaceImg').src=info[2];$('#spaceImg').alt=info[0]+' — illustrative concept'}));
// Gallery filtering, fullscreen viewer and keyboard navigation.
const modal=$('#imageModal'),modalImg=$('#modalImg');let galleryItems=[],photoIndex=0,returnFocus;
function visiblePhotos(){return $$('[data-lightbox],.gallery-grid button').filter(el=>!el.hidden)}
function showPhoto(){const img=$('img',galleryItems[photoIndex]);modalImg.src=img.src;modalImg.alt=img.alt;$('#modalCaption').textContent=(photoIndex+1)+' / '+galleryItems.length+' · '+img.alt;$('.modal-prev').hidden=galleryItems.length<2;$('.modal-next').hidden=galleryItems.length<2;}
function closeGallery(){if(!modal.classList.contains('open'))return;modal.classList.remove('open');document.body.classList.remove('no-scroll');if(returnFocus)returnFocus.focus()}
$$('[data-lightbox],.gallery-grid button').forEach(button=>button.addEventListener('click',()=>{returnFocus=button;galleryItems=visiblePhotos();photoIndex=galleryItems.indexOf(button);showPhoto();modal.classList.add('open');document.body.classList.add('no-scroll');$('#closeModal').focus()}));
$('#closeModal').addEventListener('click',closeGallery);modal.addEventListener('click',e=>{if(e.target===modal)closeGallery()});function nextPhoto(step){photoIndex=(photoIndex+step+galleryItems.length)%galleryItems.length;showPhoto()}$('.modal-prev').addEventListener('click',()=>nextPhoto(-1));$('.modal-next').addEventListener('click',()=>nextPhoto(1));modal.addEventListener('keydown',e=>{trapFocus(e,modal);if(e.key==='ArrowRight')nextPhoto(1);if(e.key==='ArrowLeft')nextPhoto(-1)});
$$('[data-filter]').forEach(button=>button.addEventListener('click',()=>{$$('[data-filter]').forEach(b=>{b.classList.toggle('active',b===button);b.setAttribute('aria-pressed',String(b===button))});let count=0;$$('[data-category]').forEach(photo=>{photo.hidden=button.dataset.filter!=='all'&&photo.dataset.category!==button.dataset.filter;if(!photo.hidden)count++});$('#galleryCount').textContent=count+' CONCEPT PHOTOGRAPH'+(count===1?'':'S')}));
addEventListener('keydown',e=>{if(e.key==='Escape'){closeGallery();if(panel.classList.contains('open'))setMenu(false)}});
const faqSearch=$('#faqSearch');if(faqSearch)faqSearch.addEventListener('input',()=>{const query=faqSearch.value.toLowerCase().trim();let count=0;$$('.faq-page details').forEach(d=>{d.hidden=!d.textContent.toLowerCase().includes(query);if(!d.hidden)count++});$('#faqEmpty').hidden=count>0});
// Enquiries stay on the visitor's device unless an owner WhatsApp destination is configured.
const booking=$('#bookingForm');if(booking){const ci=$('#checkin'),co=$('#checkout'),status=$('#formStatus'),out=$('#enquiryOutput');const localDate=d=>new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,10);ci.min=localDate(new Date());co.min=ci.min;function updateDates(){if(ci.value){const next=new Date(ci.value+'T12:00:00');next.setDate(next.getDate()+1);co.min=localDate(next)}co.setCustomValidity(co.value&&ci.value&&co.value<=ci.value?'Choose a check-out date after check-in.':'');const nights=ci.value&&co.value?Math.round((new Date(co.value)-new Date(ci.value))/86400000):0;if($('#nightSummary'))$('#nightSummary').textContent=nights>0?nights+' night'+(nights===1?'':'s')+' · Subject to availability and owner confirmation':'Select your dates to see the length of your stay.'}ci.addEventListener('change',updateDates);co.addEventListener('input',updateDates);booking.addEventListener('submit',async e=>{e.preventDefault();updateDates();if(!booking.reportValidity())return;if(co.value<=ci.value){status.textContent='Please choose a check-out date after check-in.';return}const nights=Math.round((new Date(co.value)-new Date(ci.value))/86400000);let message=`Hello Alami Villa! I would like to enquire about a stay.\nName: ${$('#name').value.trim()}\nCheck-in: ${ci.value}\nCheck-out: ${co.value}\nNights: ${nights}\nGuests: ${$('#guests').value}`;if($('#email')?.value)message+='\nEmail: '+$('#email').value.trim();if($('#requests')?.value)message+='\nRequests: '+$('#requests').value.trim();message+='\nPlease share availability, rates and booking terms.';if(/^\d{8,15}$/.test(VILLA_CONFIG.whatsapp)){window.open('https://wa.me/'+VILLA_CONFIG.whatsapp+'?text='+encodeURIComponent(message),'_blank','noopener');status.textContent='Enquiry opened in WhatsApp. Please send it there; your reservation requires owner confirmation.'}else{out.textContent=message;try{await navigator.clipboard.writeText(message);status.textContent='Enquiry copied. The owner’s WhatsApp number is not yet connected. No message has been sent and no reservation has been made.'}catch{status.textContent='Your enquiry is ready below. Copy the text to share with the owner. No reservation has been made.'}}});}

// Keep viewport-driven motion aligned after rotation and mobile toolbar changes.
addEventListener('resize',()=>{if(!queued){requestAnimationFrame(updateScroll);queued=true}},{passive:true});
// Swipe between photos without interfering with pinch-to-zoom.
let swipeStart=null;
modal.addEventListener('touchstart',e=>{swipeStart=e.touches.length===1?{x:e.touches[0].clientX,y:e.touches[0].clientY}:null},{passive:true});
modal.addEventListener('touchend',e=>{if(!swipeStart||!e.changedTouches.length)return;const dx=e.changedTouches[0].clientX-swipeStart.x,dy=e.changedTouches[0].clientY-swipeStart.y;swipeStart=null;if(Math.abs(dx)>55&&Math.abs(dx)>Math.abs(dy)*1.5&&galleryItems.length>1)nextPhoto(dx<0?1:-1)},{passive:true});
modal.addEventListener('touchcancel',()=>{swipeStart=null},{passive:true});
